void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;

    /* Initialize tile coordinates based on image and tile number */
    *p_tx0 = p_image->x0;
    *p_tx1 = p_image->x1;
    *p_ty0 = p_image->y0;
    *p_ty1 = p_image->y1;

    /* Determine the minimum precinct size and maximum resolution and precision */
    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (resno = 0; resno < p_cp->tp_on ? p_cp->tp_max_layers : p_cp->numresolution; resno++) {
            OPJ_UINT32 dx = (OPJ_UINT32)(1 << p_cp->res_spec[resno][compno].dx);
            OPJ_UINT32 dy = (OPJ_UINT32)(1 << p_cp->res_spec[resno][compno].dy);
            OPJ_UINT32 num_prec = p_cp->res_spec[resno][compno].num_precincts;

            dx_min = (dx < dx_min || dx_min == 0) ? dx : dx_min;
            dy_min = (dy < dy_min || dy_min == 0) ? dy : dy_min;

            if (num_prec > max_prec) {
                max_prec = num_prec;
            }

            if (resno + 1 > max_res) {
                max_res = resno + 1;
            }
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 max_res = 0;
    OPJ_UINT32 dx = 0;
    OPJ_UINT32 dy = 0;

    *p_tx0 = 0;
    *p_tx1 = 0;
    *p_ty0 = 0;
    *p_ty1 = 0;
    *p_dx_min = 0;
    *p_dy_min = 0;

    for (compno = 0; compno < p_image->numcomps; ++compno) {
        opj_image_comp_t *comp = &p_image->comps[compno];
        opj_tcp_t *tcp = &p_cp->tcp[compno];

        for (resno = 0; resno < tcp->numresolutions; ++resno) {
            opj_tcd_tilecomp_t *tilecomp = &tcp->tcd_tilecomp[0];
            opj_tcd_resolution_t *res = &tilecomp->resolutions[resno];

            OPJ_UINT32 precno;
            OPJ_UINT32 max_precno = 0;

            for (precno = 0; precno < res->numprecincts; ++precno) {
                opj_tcd_precinct_t *precinct = &res->precincts[precno];
                dx = precinct->x1 - precinct->x0;
                dy = precinct->y1 - precinct->y0;
                if (!precno || dx < *p_dx_min) {
                    *p_dx_min = dx;
                }
                if (!precno || dy < *p_dy_min) {
                    *p_dy_min = dy;
                }
            }

            if (tcp->numresolutions > max_res) {
                max_res = tcp->numresolutions;
            }

            if (res->numprecincts > max_precno) {
                max_precno = res->numprecincts;
            }

            if (max_precno > max_prec) {
                max_prec = max_precno;
            }

            if (comp->x1 > *p_tx1) {
                *p_tx1 = comp->x1;
            }

            if (comp->y1 > *p_ty1) {
                *p_ty1 = comp->y1;
            }
        }
    }

    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno, OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1, OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec, OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 i, compno;
    OPJ_UINT32 max_res = 1;
    OPJ_UINT32 max_prec = 0;
    OPJ_UINT32 dx = 0, dy = 0;
    OPJ_UINT32 tile_w = 0, tile_h = 0;
    OPJ_INT32 tx0 = 0, ty0 = 0;

    tile_w = p_image->x1 - p_image->x0;
    tile_h = p_image->y1 - p_image->y0;

    tx0 = p_tileno % p_cp->tw;
    ty0 = p_tileno / p_cp->tw;

    *p_tx0 = p_image->x0 + (tx0 * tile_w) / p_cp->tw;
    *p_tx1 = p_image->x0 + ((tx0 + 1) * tile_w) / p_cp->tw;
    *p_ty0 = p_image->y0 + (ty0 * tile_h) / p_cp->th;
    *p_ty1 = p_image->y0 + ((ty0 + 1) * tile_h) / p_cp->th;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        for (i = 0; i < p_cp->max_res_no; i++) {
            if (p_cp->tcps[compno].resolutions[i].dx > 1) {
                dx = p_cp->tcps[compno].resolutions[i].dx;
                dy = p_cp->tcps[compno].resolutions[i].dy;
            }

            if (i + 1 > max_res) {
                max_res = i + 1;
            }

            if (p_cp->tcps[compno].resolutions[i].numres > max_prec) {
                max_prec = p_cp->tcps[compno].resolutions[i].numres;
            }
        }
    }

    *p_dx_min = dx;
    *p_dy_min = dy;
    *p_max_prec = max_prec;
    *p_max_res = max_res;
}

void calculate_tile_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                        OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                        OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                        OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_precision = 0;
    OPJ_UINT32 max_resolution = 0;
    OPJ_UINT32 dx_min = 0;
    OPJ_UINT32 dy_min = 0;
    OPJ_UINT32 num_resolutions;
    OPJ_UINT32 num_components = p_image->numcomps;

    for (compno = 0; compno < num_components; ++compno) {
        opj_image_comp_t *comp = &p_image->comps[compno];
        opj_tcp_t *tcp = &p_cp->tcp[compno];

        *p_tx0 = (OPJ_INT32)(comp->x0 + (p_tileno % p_cp->tw) * p_cp->tx);
        *p_tx1 = (OPJ_INT32)(OPJ_MIN(*p_tx0 + p_cp->tx, comp->x1));
        *p_ty0 = (OPJ_INT32)(comp->y0 + (p_tileno / p_cp->tw) * p_cp->ty);
        *p_ty1 = (OPJ_INT32)(OPJ_MIN(*p_ty0 + p_cp->ty, comp->y1));

        for (resno = 0; resno < tcp->numresolutions; ++resno) {
            opj_tccp_t *tccp = &tcp->tccp[resno];

            if (resno > max_resolution) {
                max_resolution = resno;
            }

            if (resno == 0) {
                dx_min = tccp->dx;
                dy_min = tccp->dy;
            } else {
                if (tccp->dx < dx_min) {
                    dx_min = tccp->dx;
                }
                if (tccp->dy < dy_min) {
                    dy_min = tccp->dy;
                }
            }

            num_resolutions = resno + 1;
            if (num_resolutions > max_precision) {
                max_precision = num_resolutions;
            }
        }
    }

    *p_dx_min = dx_min;
    *p_dy_min = dy_min;
    *p_max_prec = max_precision;
    *p_max_res = max_resolution + 1;
}

void calculate_encoding_parameters(const opj_image_t *p_image, const opj_cp_t *p_cp, OPJ_UINT32 p_tileno,
                                   OPJ_INT32 *p_tx0, OPJ_INT32 *p_tx1, OPJ_INT32 *p_ty0, OPJ_INT32 *p_ty1,
                                   OPJ_UINT32 *p_dx_min, OPJ_UINT32 *p_dy_min, OPJ_UINT32 *p_max_prec,
                                   OPJ_UINT32 *p_max_res) {
    OPJ_UINT32 compno;
    OPJ_UINT32 resno;
    OPJ_UINT32 max_precision = 0;

    *p_tx0 = p_cp->tx0 + (p_tileno % p_cp->num_tx) * p_cp->tdim_x;
    *p_tx1 = *p_tx0 + p_cp->tdim_x;
    *p_ty0 = p_cp->ty0 + (p_tileno / p_cp->num_tx) * p_cp->tdim_y;
    *p_ty1 = *p_ty0 + p_cp->tdim_y;

    *p_dx_min = 0xFFFFFFFF;
    *p_dy_min = 0xFFFFFFFF;

    for (compno = 0; compno < p_image->numcomps; compno++) {
        OPJ_UINT32 numres = p_cp->tcps[compno].num_resolutions;

        *p_max_res = OPJ_MAX(*p_max_res, numres);

        for (resno = 0; resno < numres; resno++) {
            OPJ_UINT32 dx = p_cp->tcps[compno].tx0 + resno == 0 ? 1 : p_cp->tcps[compno].res_spec[resno - 1].dx;
            OPJ_UINT32 dy = p_cp->tcps[compno].ty0 + resno == 0 ? 1 : p_cp->tcps[compno].res_spec[resno - 1].dy;

            *p_dx_min = OPJ_MIN(*p_dx_min, dx);
            *p_dy_min = OPJ_MIN(*p_dy_min, dy);
            max_precision = resno + 1;
        }
    }

    *p_max_prec = max_precision;
}
